function removeTimestampLines(text) {
  return text
    .split("\n")
    .filter((line) => {
      const value = line.trim();

      if (!value) return true;

      const startsWithTimestamp =
        /^(\d{1,2}:)?\d{1,2}:\d{2}\s/.test(value) ||
        /^(\d{1,2}:)?\d{1,2}:\d{2}\s*[-–—]/.test(value);

      const hasManyTimestamps =
        (value.match(/\b(\d{1,2}:)?\d{1,2}:\d{2}\b/g) || []).length >= 2;

      const isPurePromoLine =
        /instagram|tiktok|linkedin|newsletter|podcast|speaker|abo|abonnieren|community|workshop|masterclass|kostenfrei|rabatt|code:|hostinger|lebensbalance|produktivitätssystem|socials|whatsapp|substack|kraken|papierkram|typeform|hosting|vps/i.test(value) &&
        value.length < 320;

      return !startsWithTimestamp && !hasManyTimestamps && !isPurePromoLine;
    })
    .join("\n")
    .trim();
}

function removeHashtagNoise(text) {
  return text
    .replace(/#[\p{L}\p{N}_-]+/gu, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function removeLongSeparatorNoise(text) {
  return text
    .replace(/_{5,}/g, " ")
    .replace(/-{5,}/g, " ")
    .replace(/={5,}/g, " ")
    .replace(/MB[0-9A-Z]{8,}/g, "")
    .trim();
}

function protectAbbreviations(text) {
  return text
    .replace(/Prof\.\s*Dr\./g, "Prof Dr")
    .replace(/Dr\./g, "Dr")
    .replace(/z\.\s*B\./g, "zum Beispiel")
    .replace(/bzw\./g, "beziehungsweise")
    .replace(/ca\./g, "circa");
}

function splitIntoSentences(text) {
  const normalized = protectAbbreviations(cleanWhitespace(text).replace(/\n+/g, " "));
  const matches = normalized.match(/[^.!?]+[.!?]+|[^.!?]+$/g);

  return (matches || [normalized])
    .map((sentence) => sentence.trim())
    .filter(Boolean);
}

