}

function limitText(text, maxLength) {
  const value = cleanWhitespace(text);

  if (value.length <= maxLength) {
    return value;
  }

  const shortened = value.slice(0, maxLength);
  const lastSentenceEnd = Math.max(
    shortened.lastIndexOf("."),
    shortened.lastIndexOf("!"),
    shortened.lastIndexOf("?")
  );

  if (lastSentenceEnd > maxLength * 0.55) {
    return shortened.slice(0, lastSentenceEnd + 1).trim();
  }

  return shortened.trim() + "…";
}

function buildFallbackText(item, title) {
  const category = toText(item.category || "KI");
  const sourceName = toText(item.sourceName || item.source || "der Quelle");

  if (category === "AI Workflows") {
    return `Dieses Signal aus ${sourceName} behandelt „${title}“. Es sollte geprüft werden, ob daraus ein relevanter Use Case für Automatisierung, Agenten-Workflows, Produktivität oder interne KI-Prozesse entsteht.`;
  }

  if (category === "AI Infrastructure") {
    return `Dieses Signal aus ${sourceName} behandelt „${title}“. Es sollte geprüft werden, ob die Entwicklung für KI-Infrastruktur, Developer-Tools, Rechenleistung oder technische Grundlagen relevant ist.`;
  }

  if (category === "AI Research") {
    return `Dieses Signal aus ${sourceName} behandelt „${title}“. Es sollte geprüft werden, ob daraus Hinweise auf neue Modelle, Forschungsergebnisse, Benchmarks oder technische Fortschritte entstehen.`;
  }

  if (category === "AI Product Demo" || category === "Launches & Tool-Updates") {
    return `Dieses Signal aus ${sourceName} behandelt „${title}“. Es sollte geprüft werden, ob daraus relevante Produktfunktionen, Tool-Updates oder neue Anwendungsmöglichkeiten entstehen.`;
  }

  return `Dieses Signal aus ${sourceName} behandelt „${title}“. Es sollte geprüft werden, ob daraus ein relevanter KI-Trend oder ein konkreter Anwendungsfall entsteht.`;
}

function cleanArticleText(rawText, fallbackTitle, item) {
  let text = toText(rawText);

  if (!text) {
    text = toText(fallbackTitle);
  }

  text = cleanWhitespace(text);
  text = cutAtFirstTimestampBlock(text);
  text = cutBeforePromoBlocks(text);
  text = removeTimestampLines(text);
  text = removeUrls(text);
  text = removeHashtagNoise(text);
  text = removeLongSeparatorNoise(text);
  text = removeEmojis(text);
  text = removeCallToActionFragments(text);
  text = removePromoSentences(text);
  text = removeDanglingLinkPhrases(text);
  text = cleanWhitespace(text);

  const titleOnly =
    text.toLowerCase() === toText(fallbackTitle).toLowerCase() ||
    text.length < 80;

  if (titleOnly || containsTooMuchPromo(text)) {
    return buildFallbackText(item, fallbackTitle);
  }

  return text;
}

function createSummary(cleanedText, fallbackTitle, item) {
  const sentences = splitIntoSentences(cleanedText);

  let summary = sentences.slice(0, 2).join(" ");

  if (!summary || summary.length < 80 || containsTooMuchPromo(summary)) {
    summary = buildFallbackText(item, fallbackTitle);
  }

  return limitText(summary, 520);
}

function createArticleBody(cleanedText, fallbackTitle, item) {
  const sentences = splitIntoSentences(cleanedText);

  let body = sentences.slice(0, 8).join(" ");

  if (!body || body.length < 120 || containsTooMuchPromo(body)) {
    body = buildFallbackText(item, fallbackTitle);
  }

  return limitText(body, 2200);
}

function improveBusinessImpact(item) {
  const name = toText(item.name || item.articleTitle);
  const category = toText(item.category);

  const categoryText = {
    "AI Tools": "neue KI-Tools, Entwicklerwerkzeuge, Agenten oder produktnahe KI-Anwendungen",
    "AI Workflows": "neue Automatisierungs-, Agenten- oder Produktivitätsmöglichkeiten mit KI",
    "AI Infrastructure": "KI-Infrastruktur, Developer-Tools, Rechenleistung oder technische Grundlagen für KI-Systeme",
    "AI Product Demo": "offizielle Produktfunktionen, Demos oder neue Anwendungsmöglichkeiten",
    "AI Research": "neue Modelle, Forschungsergebnisse, Sicherheitsfragen oder technische Fortschritte",
    "Launches & Tool-Updates": "neue Produktfunktionen, Tool-Updates oder marktnahe KI-Entwicklungen",
    "Workflows": "neue Arbeitsabläufe, Automatisierungen oder Produktivitätsprozesse",
  };

  const reason =
    categoryText[category] ||
    "neue KI-Entwicklungen, Tools oder relevante Marktsignale";

  return `Dieses Signal ist relevant, weil es auf ${reason} hinweist: ${name}`;
}

function improveRecommendation(item) {
  const status = toText(item.status);
  const category = toText(item.category);

  if (status.toLowerCase().includes("hoch")) {
    return `Für das Trend-Radar priorisieren und prüfen, ob daraus ein konkreter Use Case im Bereich ${category || "KI"} entsteht.`;
  }

  return `Weiter beobachten und prüfen, ob sich daraus ein relevanter Trend im Bereich ${category || "KI"} entwickelt.`;
}

return items.map((item) => {
  const input = item.json || {};

  const title = toText(input.articleTitle || input.name || "Unbenanntes Signal");

  const rawText =
    input.articleBody ||
    input.articleSummary ||
    input.summary ||
    input.description ||
    input.name ||
    "";

  const cleanedText = cleanArticleText(rawText, title, input);

  const articleSummary = createSummary(cleanedText, title, input);
  const articleBody = createArticleBody(cleanedText, title, input);

  const output = {
    ...input,

    summary: articleSummary,
    businessImpact: improveBusinessImpact(input),
    recommendation: improveRecommendation(input),

    articleTitle: title,
    articleSummary,
    articleBody,

    sourceName: toText(input.sourceName || input.source),
    sourceUrl: toText(input.sourceUrl),
    publishedAt: toText(input.publishedAt),
  };

  return {
    json: output,
  };
});
